package com.brainserve.onboarding.notifications.api.controller;
import com.brainserve.onboarding.common.api.ApiResponse;import com.brainserve.onboarding.common.observability.RequestContext;import com.brainserve.onboarding.common.security.TenantPrincipal;import com.brainserve.onboarding.notifications.api.response.NotificationDeliveryResponse;import com.brainserve.onboarding.notifications.infrastructure.persistence.NotificationDeliveryRepository;import java.util.*;import org.springframework.data.domain.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/notification-deliveries") @PreAuthorize("hasAuthority('NOTIFICATION_MANAGE')") public class NotificationDeliveryController {private final NotificationDeliveryRepository repo;public NotificationDeliveryController(NotificationDeliveryRepository repo){this.repo=repo;}@GetMapping ApiResponse<List<NotificationDeliveryResponse>> list(@AuthenticationPrincipal TenantPrincipal p,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="50")int size){var x=repo.findAllByOrganizationId(p.organizationId(),PageRequest.of(Math.max(0,page),Math.min(100,Math.max(1,size)),Sort.by(Sort.Direction.DESC,"createdAt")));var items=x.getContent().stream().map(d->new NotificationDeliveryResponse(d.getId(),d.getNotificationId(),d.getChannel(),d.getRecipientAddress(),d.getStatus(),d.getAttemptCount(),d.getNextAttemptAt(),d.getSentAt(),d.getDeliveredAt(),d.getLastError(),d.getCreatedAt())).toList();return ApiResponse.success(items,Map.of("page",x.getNumber(),"size",x.getSize(),"totalElements",x.getTotalElements(),"totalPages",x.getTotalPages()),RequestContext.requestId());}}
